    let here = get(&s, s.pos)
    if here == c {
        return true
    }
    return contains(&s, c)
}

fn remove(s: &Str, c: Str) -> Str {
    if s.pos >= len(&s) {
        return clone(&s)
    }
    let here = get(&s, s.pos)
    if here == c {
        let new_data = clone(&s)
        drop new_data
        new_data.pos = s.pos + 1
        return new_data
    }
    return remove(&s, c)
}

